import Redis from "ioredis";

const redis = new Redis(process.env.REDIS_URL);

// ZSET: member = shopper token, score = join timestamp (lowest score = front of line)
const WAITING_KEY = "flash_sale:waiting_room";
// SET: shoppers currently granted a checkout slot; SET size == effective capacity
const ADMITTED_KEY = "flash_sale:admitted";

/**
 * Called when a shopper enters the waiting room.
 * Not under review — included for context only.
 */
export async function join(token: string): Promise<void> {
  await redis.zadd(WAITING_KEY, Date.now(), token);
}

/**
 * Background admit worker: runs on a short interval (e.g. every 500ms) and
 * may be triggered from multiple app instances, so overlapping/concurrent
 * calls to admit(n) are possible.
 *
 * Pulls the front `n` shoppers off the waiting queue and grants them a
 * checkout slot.
 */
export async function admit(n: number): Promise<string[]> {
  // Step 1 (READ): peek the front n lowest-score tokens, but don't remove them yet.
  const tokens = await redis.zrange(WAITING_KEY, 0, n - 1);

  if (tokens.length === 0) {
    return [];
  }

  // Step 2 (REMOVE): a separate command that deletes those same tokens from the
  // queue. Anything can happen to WAITING_KEY between step 1 and here.
  await redis.zrem(WAITING_KEY, ...tokens);

  // Step 3 (GRANT): insert the tokens into the admitted set. Note there is no
  // redis.expire(ADMITTED_KEY, ttlSeconds) call anywhere in this module, and no
  // per-token TTL either — admitted members stay here forever once inserted.
  await redis.sadd(ADMITTED_KEY, ...tokens);

  return tokens;
}
